function steps(level) {
  let text = "";

  switch (level) {
    case 3:
      text += "c";
    case 2:
      text += "b";
    case 1:
      text += "a";
      break;
    default:
      text += "?";
  }

  return text;
}

console.log(steps(3));
console.log(steps(1));
console.log(steps("2"));
